// -------------------------------------------------------------------
// Copyright (C) 2019 Ahmed Shahein
// -------------------------------------------------------------------
//
// -------------------------------------------------------------------
module filt_cicd #(
  parameter gp_decimation_factor = 4,
  parameter gp_order             = 3,
  parameter gp_diff_delay        = 1,
  parameter gp_phase             = 0,
  parameter gp_inp_width         = 8,
  parameter gp_oup_width         = gp_inp_width + gp_order*$clog2(gp_decimation_factor*gp_diff_delay)
) (
  input  wire                           i_rst_an,
  input  wire                           i_ena,
  input  wire                           i_clk,
  input  wire signed [gp_inp_width-1:0] i_data,
  output wire signed [gp_oup_width-1:0] o_data
);
// -------------------------------------------------------------------
  // CONSTANT DECLARATION
  localparam c_fill_width = gp_oup_width - gp_inp_width;
  // REGISTER DECLARATION
  wire w_sclk;
  wire signed [gp_oup_width-1         :0] r_comb_inp;  
  reg         [gp_decimation_factor-1 :0] r_count;
  wire signed [gp_order*gp_oup_width-1:0] r_int_dly;
  wire signed [gp_order*gp_oup_width-1:0] r_comb_dly;
  // WIRE DECLARATION
  wire signed [gp_oup_width-1         :0] w_data;
  wire signed [gp_order*gp_oup_width-1:0] w_int_add;
  wire signed [gp_order*gp_oup_width-1:0] w_comb_diff;
// -------------------------------------------------------------------   
  genvar i;
// -------------------------------------------------------------------  
  /****************/
  /* RING COUNTER */
  /****************/
  always @(posedge i_clk or negedge i_rst_an)
    begin: p_ring_counter
      if (!i_rst_an)
        begin
	  r_count <= 'd0;
	end
      else if (i_ena)
       begin
         if (r_count=='d0)
           r_count[0] <= 1'b1;
	 else
	   begin
	     r_count[0] <= r_count[gp_decimation_factor-1];
	     r_count[gp_decimation_factor-1:1] <= r_count[gp_decimation_factor-2:0];
	   end
       end
    end

  /*********************/
  /* INPUT MSB PADDING */
  /*********************/
  assign w_data = {{c_fill_width{i_data[gp_inp_width-1]}},i_data};

===stimuli.m head===
  close all
  clear
  clc  

  nr_samples = 2^12;

  gp_decimation_factor  = 17;
  gp_order              = 8;
  gp_diff_delay         = 1;
  gp_phase              = 3;
  gp_inp_width          = 2;
  gp_oup_width          = gp_inp_width + gp_order*ceil(log2(gp_decimation_factor*gp_diff_delay));

  %G = % 0.5->1
  BG = gp_order * ceil(log2(gp_decimation_factor*gp_diff_delay)) + gp_inp_width
  SF = 2^(gp_order*ceil(log2(gp_decimation_factor*gp_diff_delay)))/((gp_decimation_factor*gp_diff_delay)^gp_order) %[1; 2)
  for i = 1 : 9,
    testcase = i;
    printf("### INFO: Running test-case %d\n", testcase);
  switch (testcase)
    case {1}
      nr_samples = 2^8;
      data = zeros(1, nr_samples);
      data(2)   = 1;
      data(100) = 1;
      data(180) = 1;
      data(220) = 1;

    case {2}
      nr_samples = 2^8;
      data = ones(1, nr_samples); 
      data(1) = 0;
      data(2) = 0;
      data(100:101) = 0;
      data(180:181) = 0;
      data(220:221) = 0; 

    case {3}
      data = -2^(gp_inp_width-1):2^(gp_inp_width-1)-1;

    case {4}
      data = 2^(gp_inp_width-1)-1:-1:-2^(gp_inp_width-1);    

    case {5}
      fs = 1e3;
      f1 = 1;
      f2 = fs/2;
      t = 1:1/fs:5;
      data = chirp (t, f1, 5, f2, "logarithmic");
      q_data = quantize(data, gp_inp_width, "midtread", "signed");
      data = round( 2^(gp_inp_width-1) * q_data );
      %data(data==2^(gp_inp_width-1)) = 2^(gp_inp_width-1)-1;

    case {6}
      rand ("state", 42);
      r_min = -2^(gp_inp_width-1);
      r_max =  2^(gp_inp_width-1);
      r     = floor(r_min + (r_max - r_min)*rand(1, nr_samples));
      data = r;

    case {7}
      fs    = 1e3;
      fo    = 113;
      A     = 1;
      phi   = 0;
      dc    = 0;
      c     = 10;
      t     = 0:1/fs:c/fo-1/fs;
      data  = round( 2^(gp_inp_width-1) * (A * sin(2*pi*fo*t + phi) + dc) );
      data(data==2^(gp_inp_width-1)) = 2^(gp_inp_width-1)-1;

    case {8}
      fs    = 1e3;
      fo    = 113;
      A     = 1;
      phi   = 0;
      dc    = 0;
      c     = 31;
      t     = 0:1/fs:c/fo-1/fs;
      data  = A * sin(2*pi*fo*t + phi) + dc;

